                // Check if already exists to avoid duplicates
                var exists = await _context.NEW_QUESTION_SETS
                    .AnyAsync(nqs => nqs.Set_Name == "Standards" && nqs.Question_Id == questionId, cancellationToken);

                if (!exists)
                {
                    _context.NEW_QUESTION_SETS.Add(new NEW_QUESTION_SETS
                    {
                        Set_Name = "Standards",
                        Question_Id = questionId
