        // Refactored from stored procedure [dbo].[GetChildrenAnswers]
        // Original: Simple JOIN between MATURITY_QUESTIONS and ANSWER tables with WHERE filters
        public virtual async Task<List<GetChildrenAnswersResult>> GetChildrenAnswersAsync(int? parent_Id, int? assess_Id, OutputParameter<int> returnValue = null, CancellationToken cancellationToken = default)
        {
            returnValue?.SetValue(0);

            return await _context.MATURITY_QUESTIONS
                .Join(_context.ANSWER,
                    mq => mq.Mat_Question_Id,
                    a => a.Question_Or_Requirement_Id,
                    (mq, a) => new { MatQuestion = mq, Answer = a })
                .Where(x => x.MatQuestion.Parent_Question_Id == parent_Id && x.Answer.Assessment_Id == assess_Id)
                .Select(x => new GetChildrenAnswersResult
                {
                    Mat_Question_Id = x.MatQuestion.Mat_Question_Id,
                    Question_Title = x.MatQuestion.Question_Title,
                    Question_Text = x.MatQuestion.Question_Text,
                    Answer_Text = x.Answer.Answer_Text,
                    Maturity_Level_Id = x.MatQuestion.Maturity_Level_Id,
                    Parent_Question_Id = x.MatQuestion.Parent_Question_Id,
                    Ranking = x.MatQuestion.Ranking,
                    Grouping_Id = x.MatQuestion.Grouping_Id
                })
                .ToListAsync(cancellationToken);
        }

