        public virtual async Task<List<InScopeQuestionsResult>> InScopeQuestionsAsync(int? assessment_id, OutputParameter<int> returnValue = null, CancellationToken cancellationToken = default)
        {
            returnValue?.SetValue(0);

            // Get the Universal_Sal_Level for the assessment
            var universalSalLevel = await (
                from ss in _context.STANDARD_SELECTION
                join ul in _context.UNIVERSAL_SAL_LEVEL on ss.Selected_Sal_Level equals ul.Full_Name_Sal
                where ss.Assessment_Id == assessment_id
                select ul.Universal_Sal_Level1
            ).FirstOrDefaultAsync(cancellationToken);

            // Get distinct Question_Ids that are in scope
            return await (
                from s in _context.NEW_QUESTION_SETS
                join v in _context.AVAILABLE_STANDARDS on s.Set_Name equals v.Set_Name
                join l in _context.NEW_QUESTION_LEVELS on s.New_Question_Set_Id equals l.New_Question_Set_Id
                where v.Selected == true
                    && v.Assessment_Id == assessment_id
                    && l.Universal_Sal_Level == universalSalLevel
                select new InScopeQuestionsResult { Question_Id = s.Question_Id }
            ).Distinct().ToListAsync(cancellationToken);
        }

        public virtual async Task<List<InScopeRequirementsResult>> InScopeRequirementsAsync(int? assessment_id, OutputParameter<int> returnValue = null, CancellationToken cancellationToken = default)
        {
            returnValue?.SetValue(0);

            // Get the Universal_Sal_Level for the assessment
            var universalSalLevel = await (
                from ss in _context.STANDARD_SELECTION
                join ul in _context.UNIVERSAL_SAL_LEVEL on ss.Selected_Sal_Level equals ul.Full_Name_Sal
                where ss.Assessment_Id == assessment_id
                select ul.Universal_Sal_Level1
            ).FirstOrDefaultAsync(cancellationToken);

            // Get Requirement_Ids that are in scope
            return await (
                from s in _context.REQUIREMENT_SETS
                join av in _context.AVAILABLE_STANDARDS on s.Set_Name equals av.Set_Name
                join rl in _context.REQUIREMENT_LEVELS on s.Requirement_Id equals rl.Requirement_Id
                where av.Selected == true
                    && av.Assessment_Id == assessment_id
                    && rl.Level_Type == "NST"
                    && rl.Standard_Level == universalSalLevel
                select new InScopeRequirementsResult { Requirement_Id = s.Requirement_Id }
            ).ToListAsync(cancellationToken);
        }

