        // Refactored from stored procedure [dbo].[usp_GetAssessmentPie]
        // Original: LEFT JOIN between ANSWER_LOOKUP and aggregated ANSWER data with percentage calculation
        public virtual async Task<List<usp_GetAssessmentPieResult>> usp_GetAssessmentPieAsync(int? assessment_Id, OutputParameter<int> returnValue = null, CancellationToken cancellationToken = default)
        {
            returnValue?.SetValue(0);

            // Get aggregated answer counts and percentages
            var answerStats = await _context.ANSWER
                .Where(a => a.Assessment_Id == assessment_Id)
                .GroupBy(a => a.Answer_Text)
                .Select(g => new
                {
                    Answer_Text = g.Key,
                    vcount = g.Count(),
                    Total = _context.ANSWER.Where(a => a.Assessment_Id == assessment_Id).Count()
                })
                .ToListAsync(cancellationToken);

            // Calculate percentages and join with ANSWER_LOOKUP
            return await _context.ANSWER_LOOKUP
                .GroupJoin(answerStats,
                    l => l.Answer_Text,
                    s => s.Answer_Text,
                    (l, stats) => new { Lookup = l, Stats = stats.DefaultIfEmpty() })
                .SelectMany(x => x.Stats.DefaultIfEmpty(),
                    (lookup, stat) => new usp_GetAssessmentPieResult
                    {
                        Answer_Text = lookup.Lookup.Answer_Text,
                        Answer_Full_Name = lookup.Lookup.Answer_Full_Name,
                        vcount = stat != null ? stat.vcount : 0,
                        value = stat != null && stat.Total > 0
                            ? Math.Round((decimal)stat.vcount * 100.0m / stat.Total, 1)
                            : 0m
                    })
                .ToListAsync(cancellationToken);
        }

